<?phpfunction translit_init() {	ossn_register_page('translit', 'translit_pages');	/* 	this picks up components/translit/plugins/default/css.php 			where css/weather is added the .php to it*/	ossn_extend_view('css/ossn.default', 'css/translit');/* 	this picks up components/translit/plugins/default/js.php 			where js/weather is added the .php to it*/			ossn_extend_view('js/opensource.socialnetwork', 'js/translit');	  	  if (ossn_isLoggedin()) {       		$icon = ossn_site_url('components/translit/image/translit.png');    	ossn_register_sections_menu('newsfeed', array(		    'name' => 'translit', /* this adds the name to the class thus .menu-section-item-weather */        	'text' => ossn_print('translit:title'),/* this is taken from the components/translit/locale/ossn.en.php */        	'url' => ossn_site_url('translit'),/* this results to the URL to http://yoursite.com/translit */			/* 	setting 'icon' to true will remove the <i class="fa"></i> with the font-awesome icon*/        	 'icon' => $icon,		 'section' => 'links'	    	));		    }}function translit_pages($pages) { if (!ossn_isLoggedin()) {            ossn_error_page();   }$title = ossn_print('translit:title');   $contents['content'] = ossn_plugin_view('translit/translit');   $content = ossn_set_page_layout('contents', $contents);   echo ossn_view_page($title, $content);}ossn_register_callback('ossn', 'init', 'translit_init');